try {
  var input = $('Execute Workflow Trigger').first().json;
  var toolCallId = input.toolCallId || '';
  var rawDate = (input.toolArgs && input.toolArgs.date) ? input.toolArgs.date : '';
  if (!rawDate) {
    return [{ json: { toolCallId: toolCallId, parseError: true, errorResult: 'I need a date to check availability. Which day were you thinking?' } }];
  }
  var now = new Date();
  var month = now.getUTCMonth() + 1;
  var bstOffsetHours = (month >= 3 && month <= 10) ? 1 : 0;
  var targetDate = null;
  var normalized = rawDate.toLowerCase().trim();
  if (normalized === 'today') {
    targetDate = new Date(now);
  } else if (normalized === 'tomorrow') {
    targetDate = new Date(now);
    targetDate.setUTCDate(targetDate.getUTCDate() + 1);
  } else {
    var dayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
    var dayIndex = -1;
    for (var d = 0; d < dayNames.length; d++) {
      if (normalized.indexOf(dayNames[d]) !== -1) { dayIndex = d; break; }
    }
    if (dayIndex !== -1) {
      var currentDay = now.getUTCDay();
      var daysUntil = (dayIndex - currentDay + 7) % 7;
      if (daysUntil === 0) daysUntil = 7;
      targetDate = new Date(now);
      targetDate.setUTCDate(targetDate.getUTCDate() + daysUntil);
    } else {
      var parsed = new Date(rawDate);
      if (!isNaN(parsed.getTime())) { targetDate = parsed; }
    }
  }
  if (!targetDate) {
    return [{ json: { toolCallId: toolCallId, parseError: true, errorResult: "I had trouble understanding that date. Could you say something like 'next Tuesday' or '14th April'?" } }];
  }
  var year = targetDate.getUTCFullYear();
  var mon = targetDate.getUTCMonth();
  var day = targetDate.getUTCDate();
  var timeMin = new Date(Date.UTC(year, mon, day, 9 - bstOffsetHours, 0, 0)).toISOString();
  var timeMax = new Date(Date.UTC(year, mon, day, 17 - bstOffsetHours, 0, 0)).toISOString();
  var dayLabels = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  var monthLabels = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  var dateLabel = dayLabels[targetDate.getUTCDay()] + ', ' + targetDate.getUTCDate() + ' ' + monthLabels[targetDate.getUTCMonth()];
  return [{ json: { toolCallId: toolCallId, parseError: false, timeMin: timeMin, timeMax: timeMax, dateLabel: dateLabel, targetDateISO: targetDate.toISOString().split('T')[0], bstOffsetHours: bstOffsetHours } }];
} catch(e) {
  return [{ json: { toolCallId: ($('Execute Workflow Trigger').first().json.toolCallId || ''), parseError: true, errorResult: 'I had trouble checking availability. Could you try a different date?' } }];
}

try {
  var parsedData = $('Parse Availability Date').first().json;
  var toolCallId = parsedData.toolCallId || '';
  var dateLabel = parsedData.dateLabel || 'that day';
  var bstOffsetHours = parsedData.bstOffsetHours || 0;
  var targetDateISO = parsedData.targetDateISO || '';
  var events = $input.all().map(function(item) { return item.json; });

  // Detect Calendar API error item — onError:continueRegularOutput passes error as item
  if (events.length > 0 && typeof events[0].error !== 'undefined') {
    return [{ json: { results: [{ toolCallId: toolCallId, result: "I'm having trouble checking the calendar right now. Let me have our team confirm a time with you directly." }] } }];
  }

  var bookedSlots = [];
  events.forEach(function(ev) {
    if (ev.start && ev.start.dateTime) {
      bookedSlots.push({
        start: new Date(ev.start.dateTime),
        end: ev.end && ev.end.dateTime ? new Date(ev.end.dateTime) : new Date(new Date(ev.start.dateTime).getTime() + 3600000)
      });
    }
  });
  var hours = [9,10,11,12,13,14,15,16];
  var availableSlots = [];
  hours.forEach(function(hour) {
    var utcHour = hour - bstOffsetHours;
    var slotStart = new Date(targetDateISO + 'T' + ('0' + utcHour).slice(-2) + ':00:00.000Z');
    var slotEnd = new Date(slotStart.getTime() + 3600000);
    var isBooked = false;
    for (var i = 0; i < bookedSlots.length; i++) {
      if (slotStart < bookedSlots[i].end && slotEnd > bookedSlots[i].start) { isBooked = true; break; }
    }
    if (!isBooked) {
      var period = hour >= 12 ? 'pm' : 'am';
      var display = hour > 12 ? hour - 12 : hour;
      availableSlots.push(display + period);
    }
  });
  var result;
  if (availableSlots.length === 0) {
    result = dateLabel + ' is fully booked. Could you try another day, or would you like our team to call you back to arrange a time?';
  } else if (availableSlots.length === 1) {
    result = 'I have one slot available on ' + dateLabel + ' at ' + availableSlots[0] + '. Does that work for you?';
  } else {
    var shown = availableSlots.slice(0, 3);
    var suffix = availableSlots.length > 3 ? ' and more' : '';
    result = 'I have slots available on ' + dateLabel + ' at ' + shown.join(', ') + suffix + '. Which time works best for you?';
  }
  return [{ json: { results: [{ toolCallId: toolCallId, result: result }] } }];
} catch(e) {
  var tid = '';
  try { tid = $('Parse Availability Date').first().json.toolCallId || ''; } catch(e2) {}
  return [{ json: { results: [{ toolCallId: tid, result: "I'm having trouble checking the calendar right now. Let me have our team confirm a time with you directly." }] } }];
}
